def gen(rng):
    def fmt(k, a):
        return f"{len(a)} {k}\n" + " ".join(map(str, a))
    tests = [fmt(1, [5]), fmt(3, [0]), fmt(7, [1, 2, 3]), fmt(2, [-4, -3, 0, 3, 4]), fmt(10**9, [10**9, -10**9, 0, 1]), fmt(5, [5, 5, 5, 5])]
    for n in (1, 2, 4, 6, 9, 12, 15):
        for _ in range(3):
            k = rng.randint(1, 8)
            tests.append(fmt(k, [rng.randint(-30, 30) for _ in range(n)]))
    k = 1000
    tests.append(fmt(k, [rng.randint(-10**6, 10**6) * k if rng.random() < 0.5 else rng.randint(-10**9, 10**9) for _ in range(100000)]))
    tests.append(fmt(3, [rng.randint(-10**9, 10**9) for _ in range(100000)]))
    tests.append(fmt(1, [rng.randint(-10**9, 10**9) for _ in range(100000)]))
    tests.append(fmt(10**9, [rng.choice([0, 10**9, -10**9, 999999999]) for _ in range(100000)]))
    return tests
